def compute(vars):
    crude_oil_miles = vars["v1"]
    refined_products_miles = vars["v2"]
    total_miles = crude_oil_miles + refined_products_miles

    return {
        "value": total_miles,
        "trace": {
            "crude_oil_miles": crude_oil_miles,
            "refined_products_miles": refined_products_miles,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "miles"
            }
        }
    }
